// Browser-local PDF export. No external service or dependency is required.
function commissionReportData(){const rows=visibleLedger().filter(matchesCommissionFilters);const sums={total:0,released:0,paid:0,pending:0};for(const row of rows){sums.total+=row.amount;if(row.paidAt)sums.paid+=row.amount;else if(row.released)sums.released+=row.amount;else sums.pending+=row.amount;}return {title:'Relatório de comissões',company:company==='all'?'Grupo - empresas autorizadas':companyName(company),generated:new Intl.DateTimeFormat('pt-BR',{timeZone:'America/Sao_Paulo',dateStyle:'short',timeStyle:'short'}).format(new Date()),generatedBy:user().name,filters:[['Data de referência',commissionDateLabel()],['Mês',commissionMonth==='all'?'Todos':periodLabel(commissionMonth)],['Colaborador',commissionPerson==='all'?'Todos':userName(commissionPerson)],['Status',({all:'Todos',paid:'Paga',released:'Liberada',pending:'Prevista'})[commissionStatus]],['Contrato',commissionContract==='all'?'Todos':contractCode(state.contracts.find(c=>String(c.id)===commissionContract))],['Tipo',({all:'Todos',fee:'Mensalidade / venda',setup:'Implementação',extra:'Extraordinária'})[commissionType]],['Busca',commissionQuery||'Sem busca']],sums,rows:rows.map(x=>({contract:contractCode(x.contract),client:x.contract.client,company:companyName(x.contract.company),product:product(x.contract.product)?.name||'',person:userName(x.person),event:x.label,amount:x.amount,status:x.paidAt?'Paga':x.released?'Liberada':'Prevista',payer:(x.payer?userName(x.payer):'Não definido')+(x.paidAt?' · '+(x.paymentMethod||'Meio não informado'):'')+(x.paymentBatch?' · Lote '+x.paymentBatch:''),calculation:x.manual?'Valor fixo extraordinário':money(x.invoice.amount)+' × '+x.rate+'% - política v'+x.contract.version,reason:x.adjusted?'Ajuste: '+x.editReason:x.reason||'',dates:[['Venda',x.contract.start],['Vencimento',x.invoice.due],['Recebimento',x.invoice.paidAt],['Prev. pagamento',x.plannedDate],['Pagamento',x.paidAt]].map(([label,date])=>label+': '+compactDate(date))}))};}
function generateCommissionPdf(){try{const report=commissionReportData(),bytes=commissionPdfBytes(report),blob=new Blob([bytes],{type:'application/pdf'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='Comissions-comissoes-'+localToday()+'.pdf';document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);toast('PDF gerado com os filtros atuais.');}catch(e){toast('Não foi possível gerar o PDF. Tente novamente.');}}
function commissionPdfBytes(report){const W=842,H=595,M=32,widths=[150,130,80,70,110,238],pages=[];let commands=[],y=0;const fmt=n=>Number(n.toFixed(2));const winAnsi={'€':128,'‚':130,'ƒ':131,'„':132,'…':133,'†':134,'‡':135,'ˆ':136,'‰':137,'Š':138,'‹':139,'Œ':140,'Ž':142,'‘':145,'’':146,'“':147,'”':148,'•':149,'–':150,'—':151,'˜':152,'™':153,'š':154,'›':155,'œ':156,'ž':158,'Ÿ':159};function literal(text){return '('+Array.from(String(text).normalize('NFC')).map(ch=>{let n=winAnsi[ch]??ch.charCodeAt(0);if(n>255)n=63;if(n===40||n===41||n===92)return '\\'+String.fromCharCode(n);if(n<32||n>126)return '\\'+n.toString(8).padStart(3,'0');return ch;}).join('')+')';}function text(value,x,top,size=9,bold=false,color='0.08 0.17 0.19'){commands.push(`BT /${bold?'F2':'F1'} ${size} Tf ${color} rg 1 0 0 1 ${fmt(x)} ${fmt(H-top)} Tm ${literal(value)} Tj ET`);}function box(x,top,w,h,color){commands.push(`${color} rg ${fmt(x)} ${fmt(H-top-h)} ${fmt(w)} ${fmt(h)} re f`);}function wrap(value,maxWidth,size){let lines=[],line='';const max=Math.max(4,Math.floor(maxWidth/(size*.57)));for(const raw of String(value||'').split('\n')){for(let word of raw.split(/\s+/)){if(!word)continue;while(word.length>max){if(line){lines.push(line);line='';}lines.push(word.slice(0,max));word=word.slice(max);}if(line&&line.length+word.length+1>max){lines.push(line);line=word;}else line+=(line?' ':'')+word;}if(line){lines.push(line);line='';}}return lines.length?lines:[''];}function begin(){commands=[];text('Comissions',M,39,20,true);text(report.title,M,60,12,true);text(report.company,M,77,9);text('Gerado em '+report.generated+' (Brasília)',548,37,8);text('Por '+report.generatedBy,548,51,8);const filters=wrap(report.filters.map(([k,v])=>k+': '+v).join('  |  '),778,8);filters.forEach((line,i)=>text(line,M,95+i*11,8,false,'0.36 0.43 0.40'));let top=103+filters.length*11;box(M,top,778,42,'0.93 0.96 0.94');[['Total',report.sums.total],['A pagar',report.sums.released],['Paga',report.sums.paid],['Pendente',report.sums.pending]].forEach(([label,value],i)=>{text(label,M+12+i*194,top+14,8);text(money(value),M+12+i*194,top+31,12,true);});y=top+57;box(M,y,778,22,'0.08 0.22 0.24');let x=M;['Contrato / cliente','Pessoa / evento','Valor','Status','Pagador','Datas'].forEach((label,i)=>{text(label,x+7,y+15,8,true,'1 1 1');x+=widths[i];});y+=22;}
function finish(){pages.push(commands.join('\n'));}
begin();if(!report.rows.length){text('Nenhuma comissão encontrada para os filtros selecionados.',M+7,y+25,10);y+=40;}report.rows.forEach((row,index)=>{const cols=[[row.contract,row.client,row.company+' - '+row.product],[row.person,row.event,row.calculation,row.reason].filter(Boolean),[money(row.amount)],[row.status],[row.payer],row.dates].map((values,i)=>values.flatMap(value=>wrap(value,widths[i]-14,i===5?8:8.5)));const height=Math.max(61,...cols.map((lines,i)=>lines.length*(i===5?11:12)+16));if(y+height>H-38){finish();begin();}if(index%2===0)box(M,y,778,height,'0.97 0.98 0.97');let x=M;cols.forEach((lines,i)=>{lines.forEach((line,n)=>text(line,x+7,y+15+n*(i===5?11:12),i===5?8:8.5,n===0&&i!==5));x+=widths[i];});commands.push(`0.88 0.91 0.89 RG .4 w ${M} ${fmt(H-y-height)} m ${W-M} ${fmt(H-y-height)} l S`);y+=height;});finish();pages.forEach((content,i)=>{commands=[];text('Comissions | '+report.rows.length+' lançamento(s) | Valores em BRL',M,H-15,7,false,'0.43 0.48 0.45');text('Página '+(i+1)+' de '+pages.length,W-112,H-15,7);pages[i]=content+'\n'+commands.join('\n');});const objects=[null,'<< /Type /Catalog /Pages 2 0 R >>','', '<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>','<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>'];const refs=[];for(const stream of pages){const pageId=objects.length,streamId=pageId+1;refs.push(pageId+' 0 R');objects.push(`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${W} ${H}] /Resources << /Font << /F1 3 0 R /F2 4 0 R >> >> /Contents ${streamId} 0 R >>`);objects.push(`<< /Length ${stream.length} >>\nstream\n${stream}\nendstream`);}objects[2]=`<< /Type /Pages /Kids [${refs.join(' ')}] /Count ${pages.length} >>`;let output='%PDF-1.4\n',offsets=[0];for(let i=1;i<objects.length;i++){offsets[i]=output.length;output+=`${i} 0 obj\n${objects[i]}\nendobj\n`;}const start=output.length;output+=`xref\n0 ${objects.length}\n0000000000 65535 f \n`;for(let i=1;i<objects.length;i++)output+=String(offsets[i]).padStart(10,'0')+' 00000 n \n';output+=`trailer\n<< /Size ${objects.length} /Root 1 0 R >>\nstartxref\n${start}\n%%EOF`;return new TextEncoder().encode(output);}
